#!/usr/bin/env bash
# =============================================================================
# HERCOSSNUX PQC IP Core - Layer 3B step 6: ML-DSA-65 Verify
#
# Twenty ACVP sigver vectors plus two CONSTRUCTED cases, with a reason code
# checked alongside every verdict.
#
# A VERDICT BIT IS NOT ENOUGH. Verify returns one bit, and a signature over
# twenty-two booleans cannot separate a rejection from a rejection for the
# right reason: under that output every rejection branch is interchangeable.
# The reason code (0 accept, 1 length, 2 hint decode, 3 z bound, 4 c_tilde
# mismatch) goes into the signature for the same reason kappa does in Sign,
# and mutation M9 -- which reports a mismatch as a hint failure while leaving
# the verdict correct -- is killed by nothing else.
#
# COVERAGE WAS MEASURED BEFORE THE RTL. The twenty ACVP vectors exercise only
# three of the five outcomes: 4 accept, 11 mismatch, 5 hint decode, and ZERO
# for the length and z-bound branches. Those two cases were constructed up
# front rather than after a mutation survived, which is the mistake this core
# has already made four times. The z-bound case sits exactly on
# GAMMA1 - BETA, the only value at which >= and > differ.
#
# This step also REPLACES codec_d, which gained a 10-bit unsigned unpack mode
# for t1. The codec signature is unchanged and is re-run below.
#
# Installs into: $HOME/vhdl_repo/IP_Cores/PQC/
# Expected final line:
#   PQC L3B DSAVER PASS cases=22 accept=4 reject=18 sig=183a67e1ba95f501
# =============================================================================
set -u
(
  set -e
  DEST="$HOME/vhdl_repo/IP_Cores/PQC"
  mkdir -p "$DEST/rtl" "$DEST/verif" "$DEST/doc"
  for f in rtl/dsa_sign.vhd rtl/sampler_d.vhd rtl/ntt_d_unit.vhd; do
    if [ ! -f "$DEST/$f" ]; then
      echo "MISSING PREREQUISITE: $f"
      exit 1
    fi
  done
  base64 -d > "$DEST/rtl/dsa_verify.vhd" << 'B64EOF'
