  chmod +x "$DEST/verif/mutate_dsaver.sh"
  cd "$DEST/verif"
  rm -rf work-obj08.cf
  ghdl -a --std=08 ../rtl/keccak_pkg.vhd ../rtl/keccak_f1600.vhd \
       ../rtl/keccak_sponge.vhd ../rtl/ntt_d_tables_pkg.vhd \
       ../rtl/pqc_round_d_pkg.vhd ../rtl/poly_mem_d.vhd \
       ../rtl/byte_mem_d.vhd ../rtl/ntt_d_unit.vhd ../rtl/sampler_d.vhd \
       ../rtl/codec_d.vhd ../rtl/dsa_verify.vhd ../rtl/dsa_verify_top.vhd \
       tb_codec_d.vhd tb_dsa_verify.vhd

  echo "--- codec still bit-identical after the t1 unpack mode ---"
  ghdl -e --std=08 tb_codec_d > /dev/null 2>&1
  ghdl -r --std=08 tb_codec_d --stop-time=300ms 2>&1 \
    | grep "CODECD PASS" | sed 's/.*(report note): //'

  ghdl -e --std=08 tb_dsa_verify > /dev/null 2>&1
  echo "--- Verify checkpoints (seconds each) ---"
  for st in 1 2 3 4; do
    ghdl -r --std=08 tb_dsa_verify -gG_STAGE=$st --stop-time=20000ms 2>&1 \
      | grep "CHECKPOINT PASS" | sed 's/.*(report note): //'
  done

  echo "--- Verify, twenty-two cases (a few minutes) ---"
  ghdl -r --std=08 tb_dsa_verify -gG_STAGE=0 --stop-time=400000ms 2>&1 \
    | grep "DSAVER PASS" | sed 's/.*(report note): //'
)
